export function demoData(n=720){let seed=42,p=58000; const rnd=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};return Array.from({length:n},(_,i)=>{const open=p; const close=Math.max(100,open*(1+(rnd()-.48)*.018+Math.sin(i/65)*.0015));const high=Math.max(open,close)*(1+rnd()*.006),low=Math.min(open,close)*(1-rnd()*.006);p=close;return {time:Date.UTC(2025,0,1)/1000+i*3600,open,high,low,close,volume:80+rnd()*600};});}
export function parseCSV(text){const rows=text.trim().replace(/^\uFEFF/,'').split(/\r?\n/);if(rows.length<3)throw Error('CSV needs a header and at least two candles.');if(rows.length>100001)throw Error('Maximum 100,000 candles per file.');const head=rows.shift().toLowerCase().split(',').map(x=>x.trim().replace(/^"|"$/g,''));const names=['time','open','high','low','close'];if(head.includes('timestamp'))head[head.indexOf('timestamp')]='time';if(head.includes('date'))head[head.indexOf('date')]='time';for(const k of names)if(!head.includes(k))throw Error('Missing column: '+k);let last=-Infinity;return rows.filter(x=>x.trim()).map((line,i)=>{const cols=line.split(',').map(x=>x.trim().replace(/^"|"$/g,''));let raw=cols[head.indexOf('time')];let time=/^\d+(\.\d+)?$/.test(raw)?Number(raw):Date.parse(raw)/1000;if(time>1e12)time/=1000;const b={time};for(const k of ['open','high','low','close','volume'])b[k]=head.includes(k)?Number(cols[head.indexOf(k)]):0;if(!Object.values(b).every(Number.isFinite)||time<=last||names.slice(1).some(k=>b[k]<=0)||b.volume<0||b.low>Math.min(b.open,b.close)||b.high<Math.max(b.open,b.close)||b.low>b.high)throw Error('Invalid candle or unsorted/duplicate timestamp at row '+(i+2));last=time;return b;});}
export function indicators(bars,fast,slow,rsiPeriod=14){const close=bars.map(b=>b.close);function sma(period){let sum=0;return close.map((v,i)=>{sum+=v;if(i>=period)sum-=close[i-period];return i>=period-1?sum/period:null;});}let gain=0,loss=0;const rsi=close.map((v,i)=>{if(!i)return null;const d=v-close[i-1];if(i<=rsiPeriod){gain+=Math.max(0,d)/rsiPeriod;loss+=Math.max(0,-d)/rsiPeriod;}else{gain=(gain*(rsiPeriod-1)+Math.max(0,d))/rsiPeriod;loss=(loss*(rsiPeriod-1)+Math.max(0,-d))/rsiPeriod;}return i<rsiPeriod?null:loss===0?(gain===0?50:100):100-100/(1+gain/loss);});return {fast:sma(fast),slow:sma(slow),rsi};}
export function validate(c){for(const k of ['capital','size','fee','slippage','fast','slow','rsiPeriod','oversold','overbought','stop','take'])if(!Number.isFinite(c[k]))throw Error('Enter a valid number for '+k);if(c.capital<=0||c.size<=0||c.size>100||c.fee<0||c.fee>5||c.slippage<0||c.slippage>5||c.stop<=0||c.stop>=100||c.take<=0)throw Error('Check capital, position size, costs and exit percentages.');if(!Number.isInteger(c.fast)||!Number.isInteger(c.slow)||!Number.isInteger(c.rsiPeriod)||c.fast<2||c.slow<=c.fast||c.slow>500||c.rsiPeriod<2||c.rsiPeriod>500)throw Error('Periods must be whole numbers; slow must exceed fast (maximum 500).');if(c.oversold<=0||c.overbought>=100||c.oversold>=c.overbought)throw Error('RSI thresholds must be between 0 and 100, with entry below exit.');if(!['cross','rsi','custom'].includes(c.strategy))throw Error('Unknown strategy.');if(c.strategy==='custom'){for(const r of [c.entry,c.exit]){if(!r||!['close','fast','slow','rsi'].includes(r.left)||!['close','fast','slow','rsi','number'].includes(r.right)||!['above','below','crossAbove','crossBelow'].includes(r.op)|| (r.right==='number'&&!Number.isFinite(r.value)))throw Error('Invalid custom rule.');}}}
export function backtest(bars,c){validate(c);if(bars.length<2)throw Error('At least two candles are required.');const ind=indicators(bars,c.fast,c.slow,c.rsiPeriod);const fee=c.fee/100,slip=c.slippage/100;let cash=c.capital,pos=null,peak=c.capital,maxDD=0;const trades=[],equity=[];const value=(key,i,num)=>key==='number'?num:key==='close'?bars[i]?.close:ind[key]?.[i];const rule=(r,i)=>{if(i<1)return false;const a=value(r.left,i),b=value(r.right,i,r.value),pa=value(r.left,i-1),pb=value(r.right,i-1,r.value);if(a==null||b==null)return false;if(r.op==='above')return a>b;if(r.op==='below')return a<b;if(pa==null||pb==null)return false;return r.op==='crossAbove'?a>b&&pa<=pb:a<b&&pa>=pb;};const entry=c.strategy==='cross'?{left:'fast',right:'slow',op:'crossAbove'}:c.strategy==='rsi'?{left:'rsi',right:'number',op:'crossAbove',value:c.oversold}:c.entry;const exit=c.strategy==='cross'?{left:'fast',right:'slow',op:'crossBelow'}:c.strategy==='rsi'?{left:'rsi',right:'number',op:'crossBelow',value:c.overbought}:c.exit;
function sell(raw,i,reason){const price=raw*(1-slip),proceeds=pos.qty*price*(1-fee),pnl=proceeds-pos.cost;cash+=proceeds;trades.push({...pos,exit:price,exitTime:bars[i].time,exitIndex:i,pnl,return:pnl/pos.cost*100,reason});pos=null;}
for(let i=0;i<bars.length;i++){const b=bars[i];let exited=false;if(pos){const stop=pos.entry*(1-c.stop/100),take=pos.entry*(1+c.take/100);if(b.open<=stop){sell(b.open,i,'Stop gap');exited=true;}else if(b.open>=take){sell(b.open,i,'Target gap');exited=true;}else if(rule(exit,i-1)){sell(b.open,i,'Signal');exited=true;}}
if(!pos&&!exited&&i<bars.length-1&&rule(entry,i-1)){const budget=cash*c.size/100,price=b.open*(1+slip),qty=budget/(price*(1+fee));cash-=budget;pos={entry:price,entryTime:b.time,entryIndex:i,qty,cost:budget};}
if(pos){const stop=pos.entry*(1-c.stop/100),take=pos.entry*(1+c.take/100);if(b.low<=stop)sell(Math.min(b.open,stop),i,'Stop loss');else if(b.high>=take)sell(take,i,'Take profit');}
if(pos&&i===bars.length-1)sell(b.close,i,'End of data');const e=cash+(pos?pos.qty*b.close:0);peak=Math.max(peak,e);const drawdown=(e-peak)/peak*100;maxDD=Math.max(maxDD,-drawdown);equity.push({time:b.time,value:e,drawdown});}
const wins=trades.filter(t=>t.pnl>0),losses=trades.filter(t=>t.pnl<0),grossProfit=wins.reduce((a,t)=>a+t.pnl,0),grossLoss=-losses.reduce((a,t)=>a+t.pnl,0);return {trades,equity,ind,net:cash-c.capital,netPct:(cash/c.capital-1)*100,maxDD,winRate:trades.length?wins.length/trades.length*100:0,profitFactor:grossLoss?grossProfit/grossLoss:grossProfit?Infinity:0,buyHold:(bars.at(-1).close/bars[0].open-1)*100};}
